window.careersData=[{id:"nhan-vien-kinh-doanh-ky-thuat",title:"Nhân viên kinh doanh kỹ thuật",department:"Kinh doanh",type:"Toàn thời gian",location:"TP. Hồ Chí Minh",deadline:"2026-09-30",experience:"1–2 năm",salary:"Thỏa thuận",openings:2,summary:"Tư vấn giải pháp lọc khí và thiết bị phòng sạch cho khách hàng doanh nghiệp.",description:["Tìm kiếm, chăm sóc khách hàng trong lĩnh vực điện tử, dược phẩm, bệnh viện và HVAC.","Khảo sát nhu cầu, phối hợp cùng kỹ thuật đề xuất giải pháp và lập báo giá.","Theo dõi hợp đồng, tiến độ giao hàng và duy trì quan hệ sau bán hàng."],requirements:["Tốt nghiệp Cao đẳng/Đại học khối kỹ thuật hoặc kinh tế.","Giao tiếp, đàm phán tốt; chủ động đi công tác khi cần.","Ưu tiên ứng viên hiểu HVAC, lọc khí hoặc bán hàng B2B."],benefits:["Thu nhập theo năng lực và thưởng doanh số.","Được đào tạo chuyên sâu về lọc khí, phòng sạch.","Đầy đủ BHXH, phép năm và hoạt động nội bộ."]},{id:"ky-su-hvac",title:"Kỹ sư HVAC",department:"Kỹ thuật",type:"Toàn thời gian",location:"Bình Dương",deadline:"2026-10-15",experience:"2 năm",salary:"Thỏa thuận",openings:2,summary:"Thiết kế, bóc tách và triển khai hệ thống HVAC, phòng sạch cho các dự án công nghiệp.",description:["Khảo sát, thiết kế hệ thống HVAC và phòng sạch.","Tính toán tải lạnh, lưu lượng gió, áp suất và bóc tách khối lượng.","Phối hợp giám sát thi công, nghiệm thu và bàn giao dự án."],requirements:["Tốt nghiệp chuyên ngành Nhiệt lạnh, Cơ điện hoặc liên quan.","Sử dụng AutoCAD; biết Revit MEP là lợi thế.","Nắm tiêu chuẩn HVAC, phòng sạch và có khả năng đi công trình."],benefits:["Phụ cấp công trình và công tác phí.","Lộ trình phát triển thành chủ trì dự án.","Được tham gia các dự án công nghiệp quy mô lớn."]},{id:"nhan-vien-san-xuat",title:"Nhân viên sản xuất",department:"Sản xuất",type:"Toàn thời gian",location:"Bình Dương",deadline:"2026-09-20",experience:"Không yêu cầu",salary:"8–12 triệu",openings:10,summary:"Tham gia dây chuyền sản xuất lọc khí và thiết bị phòng sạch tại nhà máy VAF.",description:["Vận hành công đoạn được phân công theo hướng dẫn.","Kiểm tra ngoại quan và ghi nhận thông số sản phẩm.","Tuân thủ quy trình 5S, an toàn và chất lượng nhà máy."],requirements:["Tốt nghiệp THPT trở lên, sức khỏe tốt.","Chăm chỉ, cẩn thận và có tinh thần phối hợp.","Có thể làm tăng ca theo kế hoạch sản xuất."],benefits:["Đào tạo nghề từ đầu, không yêu cầu kinh nghiệm.","Phụ cấp cơm, chuyên cần và tăng ca.","Thưởng lễ Tết, BHXH và khám sức khỏe định kỳ."]},{id:"ky-thuat-kiem-tra-hepa",title:"Kỹ thuật kiểm tra HEPA",department:"Chất lượng",type:"Toàn thời gian",location:"Bình Dương",deadline:"2026-10-05",experience:"1 năm",salary:"Thỏa thuận",openings:3,summary:"Thực hiện kiểm tra hiệu suất, độ kín và lập hồ sơ chất lượng cho lọc HEPA.",description:["Vận hành thiết bị scan test, đo chênh áp và kiểm tra rò rỉ HEPA.","Ghi nhận, phân tích kết quả và phát hành phiếu kiểm tra.","Hiệu chuẩn, bảo quản thiết bị và phối hợp xử lý lỗi."],requirements:["Tốt nghiệp Điện, Cơ khí, Môi trường hoặc ngành kỹ thuật.","Cẩn thận, trung thực và đọc hiểu tài liệu kỹ thuật.","Biết EN 1822/ISO 29463 là lợi thế."],benefits:["Đào tạo thiết bị kiểm tra chuyên dụng.","Môi trường kiểm soát chất lượng chuẩn quốc tế.","Phụ cấp kỹ thuật, đầy đủ chế độ theo luật."]},{id:"thuc-tap-sinh-marketing",title:"Thực tập sinh Marketing",department:"Marketing",type:"Thực tập",location:"TP. Hồ Chí Minh",deadline:"2026-09-15",experience:"Sinh viên",salary:"Hỗ trợ thực tập",openings:2,summary:"Sáng tạo nội dung và hỗ trợ truyền thông thương hiệu VAF trên các kênh số.",description:["Viết và biên tập nội dung website, mạng xã hội.","Hỗ trợ quay dựng nội dung tại văn phòng, nhà máy.","Theo dõi số liệu cơ bản và đề xuất chủ đề truyền thông."],requirements:["Sinh viên Marketing, Truyền thông hoặc ngành liên quan.","Viết tiếng Việt tốt; biết Canva hoặc công cụ dựng video.","Có tinh thần học hỏi và chủ động."],benefits:["Hỗ trợ thực tập và xác nhận báo cáo.","Được hướng dẫn trực tiếp, có cơ hội trở thành nhân viên chính thức.","Làm việc với thương hiệu B2B trong ngành kỹ thuật."]}];